  next = replaceExact(
    next,
    `  const ampMain  = ampAt(t - DEF_LAG);
  const ampThumb = ampAt(t);
  const sched    = schedule(t + TRANS_LEAD);
  const spin     = P.SPIN + P.SPINV * t;`,
    `  const ampMain = ampAt(t - DEF_LAG);
